export const EXEC_SOURCE = {
  LEARNED: 'learned',
  MANUAL:  'manual',
} as const;

export type ExecSource = typeof EXEC_SOURCE[keyof typeof EXEC_SOURCE];

export interface ExecutableItem {
  path: string;
  source: ExecSource;
}

export const WORKLOAD_POLICY_KIND = 'WorkloadPolicy';

export const POLICY_MODE = {
  MONITOR: 'monitor',
  PROTECT: 'protect',
};

export interface WorkloadPolicyProposalOwnerReference {
  apiVersion?: string;
  blockOwnerDeletion?: boolean;
  controller?: boolean;
  kind?: string;
  name?: string;
  uid?: string;
}

export interface WorkloadPolicyProposalMetadata {
  creationTimestamp?: string;
  generation?: number;
  name?: string;
  namespace?: string;
  ownerReferences?: WorkloadPolicyProposalOwnerReference[];
  resourceVersion?: string;
  uid?: string;
}

export interface WorkloadPolicyProposalExecutableRules {
  allowed?: string[];
}

export interface WorkloadPolicyProposalContainerRules {
  executables?: WorkloadPolicyProposalExecutableRules;
}

export interface WorkloadPolicyProposalSpec {
  rulesByContainer?: Record<string, WorkloadPolicyProposalContainerRules>;
}

export interface WorkloadPolicyProposal {
  id?: string;
  apiVersion?: string;
  kind?: string;
  metadata?: WorkloadPolicyProposalMetadata;
  spec?: WorkloadPolicyProposalSpec;
}

export const POLICY_CODE = {
  UNKNOWN:       '',
  READY:         'Ready',
  MISSING:       'Missing',
  FAILED:        'Failed',
  TRANSITIONING: 'Transitioning',
} as const;

export type PolicyCode = typeof POLICY_CODE[keyof typeof POLICY_CODE];

export interface PolicyStatus {
  code?: PolicyCode;
  message?: string;
  since?: string;
}

export interface PolicyNodeStatus extends PolicyStatus {
  nodeName?: string;
}

export interface ViolationRecord {
  id?: number;
  lastObservedTimestamp?: string;
  firstObservedTimestamp?: string;
  occurrences?: number;
  podName?: string;
  containerName?: string;
  executablePath?: string;
  nodeName?: string;
  action?: string;
  workloadName?: string;
  workloadKind?: string;
}

export interface WorkloadPolicyStatus {
  observedGeneration?: number;
  phase?: string;
  totalNodes?: number;
  successfulNodes?: number;
  transitioningNodes?: number;
  failedNodes?: number;
  nodesTransitioning?: PolicyNodeStatus[];
  nodesWithIssues?: Record<string, PolicyStatus>;
  violationCount?: number;
  activeViolationCount?: number;
  violations?: ViolationRecord[];
}

export interface WorkloadPolicySpec {
  mode?: string;
  rulesByContainer?: Record<string, WorkloadPolicyProposalContainerRules>;
}

export interface WorkloadPolicy {
  id?: string;
  apiVersion?: string;
  kind?: string;
  metadata?: WorkloadPolicyProposalMetadata;
  spec?: WorkloadPolicySpec;
  status?: WorkloadPolicyStatus;
  workloadRef?: {
    workloadName?: string;
    workloadType?: string;
    workloadLocation?: string;
    imageMap?: Record<string, string>;
  };
}

